const assert=require('node:assert/strict');const merge=require('/task/SOLUTION');
const x=[[5,8],[1,3],[3,6],[-4,-2],[12,12]];const copy=JSON.stringify(x);
assert.deepEqual(merge(x),[[-4,-2],[1,8],[12,12]]);assert.equal(JSON.stringify(x),copy);
assert.deepEqual(merge([]),[]);assert.deepEqual(merge([[1,10],[2,3],[4,9]]),[[1,10]]);
for(const y of [null,[[2,1]],[[1,2,3]],[[1,'2']],[[1,NaN]],[[1,Infinity]]])assert.throws(()=>merge(y));
console.log('all merge oracles pass');

